32	func mustCreateVote(t *testing.T, store *Store, in *CreateVoteInput) *VoteProposalView {
33		t.Helper()
34		view, existed, err := store.CreateVoteProposal(in)
35		if err != nil || existed {
36			t.Fatalf("CreateVoteProposal(%s) existed=%v err=%v", in.ID, existed, err)
37		}
38		return view
39	}
