161	// memberPaths 抽取视图中每个成员的路径/直接委托对象/最终代表，便于按编号断言。
162	func memberPaths(v *VoteProposalView) map[string]MemberView {
163		got := make(map[string]MemberView, len(v.Members))
164		for _, m := range v.Members {
165			got[m.ID] = MemberView{
166				ID:       m.ID,
167				Weight:   m.Weight,
168				Path:     append([]string(nil), m.Path...),
169				Delegate: m.Delegate,
170				Direct:   m.Direct,
171			}
172		}
173		return got
174	}
