176	func TestDelegationPathNotShortenedByRosterOrder(t *testing.T) {
177		// 复现缺陷场景：成员按 b、c、a、d 的顺序提交，委托 a→b、b→c、d→b。
178		// a 与 d 的路径必须保留中间的 b，不得显示为直接到 c。
179		store, _ := openTempStore(t, 1000)
180		defer store.Close()
181		in := &CreateVoteInput{
182			ID:      "gip-ordered-chain",
183			Members: []VoteMember{{ID: "b", Weight: 2}, {ID: "c", Weight: 4}, {ID: "a", Weight: 1}, {ID: "d", Weight: 8}},
184			Delegations: []Delegation{
185				{From: "a", To: "b"},
186				{From: "b", To: "c"},
187				{From: "d", To: "b"},
188			},
189			Quorum: 1, StartAt: 0, Deadline: 10, TimelockEnd: 10,
190		}
191		view := mustCreateVote(t, store, in)
192	
193		want := map[string]MemberView{
194			"a": {ID: "a", Weight: 1, Path: []string{"a", "b", "c"}, Delegate: "c", Direct: "b"},
195			"b": {ID: "b", Weight: 2, Path: []string{"b", "c"}, Delegate: "c", Direct: "c"},
196			"c": {ID: "c", Weight: 4, Path: []string{"c"}, Delegate: "c", Direct: ""},
197			"d": {ID: "d", Weight: 8, Path: []string{"d", "b", "c"}, Delegate: "c", Direct: "b"},
198		}
199		got := memberPaths(view)
200		assertMemberViews(t, "create", got, want)
201	
202		// 成员列表仍按首次提交顺序展示，不被路径修正重排。
203		if ids := memberIDs(view.Members); !equalStrings(ids, []string{"b", "c", "a", "d"}) {
204			t.Fatalf("member order changed: %v", ids)
205		}
206	
207		// 票重归集不变：c 代表全部 1+2+4+8=15；路径修正不改变最终代表与归集权重。
208		ballot, err := store.CastVote("gip-ordered-chain", "c", true, 5)
209		if err != nil {
210			t.Fatalf("final representative vote: %v", err)
211		}
212		if ballot.Weight != 15 {
213			t.Fatalf("group weight=%d, want 15", ballot.Weight)
214		}
215	}
