217	func TestDelegationPathsOrderIndependent(t *testing.T) {
218		// 同一组权重与委托关系，无论成员及委托参数怎样排列，
219		// 每名成员的完整路径、直接委托对象和最终代表都必须一致。
220		spec := func(id string, members []VoteMember, delegations []Delegation) *CreateVoteInput {
221			return &CreateVoteInput{
222				ID: id, Members: members, Delegations: delegations,
223				Quorum: 1, StartAt: 0, Deadline: 10, TimelockEnd: 10,
224			}
225		}
226		// 两层链 a→b→c 与 d→b 汇入 c；另有互不相连的独立链 f→g，以及自代的 e。
227		membersA := []VoteMember{
228			{ID: "b", Weight: 2}, {ID: "c", Weight: 4}, {ID: "a", Weight: 1},
229			{ID: "d", Weight: 8}, {ID: "e", Weight: 16}, {ID: "f", Weight: 32}, {ID: "g", Weight: 64},
230		}
231		delegationsA := []Delegation{
232			{From: "d", To: "b"}, {From: "a", To: "b"}, {From: "f", To: "g"}, {From: "b", To: "c"},
233		}
234		membersB := []VoteMember{
235			{ID: "g", Weight: 64}, {ID: "f", Weight: 32}, {ID: "e", Weight: 16},
236			{ID: "d", Weight: 8}, {ID: "c", Weight: 4}, {ID: "a", Weight: 1}, {ID: "b", Weight: 2},
237		}
238		delegationsB := []Delegation{
239			{From: "b", To: "c"}, {From: "f", To: "g"}, {From: "a", To: "b"}, {From: "d", To: "b"},
240		}
241		want := map[string]MemberView{
242			"a": {ID: "a", Weight: 1, Path: []string{"a", "b", "c"}, Delegate: "c", Direct: "b"},
243			"b": {ID: "b", Weight: 2, Path: []string{"b", "c"}, Delegate: "c", Direct: "c"},
244			"c": {ID: "c", Weight: 4, Path: []string{"c"}, Delegate: "c", Direct: ""},
245			"d": {ID: "d", Weight: 8, Path: []string{"d", "b", "c"}, Delegate: "c", Direct: "b"},
246			"e": {ID: "e", Weight: 16, Path: []string{"e"}, Delegate: "e", Direct: ""},
247			"f": {ID: "f", Weight: 32, Path: []string{"f", "g"}, Delegate: "g", Direct: "g"},
248			"g": {ID: "g", Weight: 64, Path: []string{"g"}, Delegate: "g", Direct: ""},
249		}
250	
251		store1, _ := openTempStore(t, 1000)
252		defer store1.Close()
253		v1 := mustCreateVote(t, store1, spec("gip-perm-1", membersA, delegationsA))
254		assertMemberViews(t, "order A", memberPaths(v1), want)
255	
256		store2, _ := openTempStore(t, 1000)
257		defer store2.Close()
258		v2 := mustCreateVote(t, store2, spec("gip-perm-2", membersB, delegationsB))
259		assertMemberViews(t, "order B", memberPaths(v2), want)
260	
261		// 同一提案换序重试：返回已有提案、不重排已保存成员、不产生新记录。
262		retry := spec("gip-perm-1", membersB, delegationsB)
263		again, existed, err := store1.CreateVoteProposal(retry)
264		if err != nil || !existed {
265			t.Fatalf("reordered retry existed=%v err=%v", existed, err)
266		}
267		if ids := memberIDs(again.Members); !equalStrings(ids, memberIDs(v1.Members)) {
268			t.Fatalf("retry reordered stored members: %v want %v", ids, memberIDs(v1.Members))
269		}
270		all, _ := store1.VoteProposals()
271		if len(all) != 1 {
272			t.Fatalf("retry created an extra proposal record: %d", len(all))
273		}
274		assertMemberViews(t, "retry", memberPaths(again), want)
275	
276		// 更深的转交链：a→b→c→d→e(停)，每个中间成员都必须出现在上游路径中。
277		deep := &CreateVoteInput{
278			ID: "gip-deep",
279			Members: []VoteMember{
280				{ID: "e", Weight: 1}, {ID: "d", Weight: 1}, {ID: "c", Weight: 1},
281				{ID: "b", Weight: 1}, {ID: "a", Weight: 1},
282			},
283			Delegations: []Delegation{
284				{From: "a", To: "b"}, {From: "b", To: "c"}, {From: "c", To: "d"}, {From: "d", To: "e"},
285			},
286			Quorum: 1, StartAt: 0, Deadline: 10, TimelockEnd: 10,
287		}
288		store3, _ := openTempStore(t, 1000)
289		defer store3.Close()
290		dv := mustCreateVote(t, store3, deep)
291		dgot := memberPaths(dv)
292		for id, p := range map[string][]string{
293			"a": {"a", "b", "c", "d", "e"},
294			"b": {"b", "c", "d", "e"},
295			"c": {"c", "d", "e"},
296			"d": {"d", "e"},
297			"e": {"e"},
298		} {
299			if !equalStrings(dgot[id].Path, p) {
300				t.Errorf("deep member %s path=%v want %v", id, dgot[id].Path, p)
301			}
302			if dgot[id].Delegate != "e" {
303				t.Errorf("deep member %s head=%s want e", id, dgot[id].Delegate)
304			}
305		}
306	}
