308	func TestDelegationPathsSurviveReopen(t *testing.T) {
309		path := filepath.Join(t.TempDir(), "treasury.json")
310		store, err := InitTreasury(path, 1000)
311		if err != nil {
312			t.Fatal(err)
313		}
314		in := &CreateVoteInput{
315			ID:      "gip-reopen-chain",
316			Members: []VoteMember{{ID: "b", Weight: 2}, {ID: "c", Weight: 4}, {ID: "a", Weight: 1}, {ID: "d", Weight: 8}},
317			Delegations: []Delegation{
318				{From: "a", To: "b"}, {From: "b", To: "c"}, {From: "d", To: "b"},
319			},
320			Quorum: 15, StartAt: 0, Deadline: 10, TimelockEnd: 10,
321			Actions: []string{"transfer:audits:15"},
322		}
323		mustCreateVote(t, store, in)
324		if _, err := store.CastVote("gip-reopen-chain", "c", true, 5); err != nil {
325			t.Fatal(err)
326		}
327		if _, err := store.TallyVote("gip-reopen-chain", 10); err != nil {
328			t.Fatal(err)
329		}
330		if _, err := store.Execute("gip-reopen-chain", 10); err != nil {
331			t.Fatal(err)
332		}
333		store.Close()
334	
335		// 关闭后重新打开：无须重新创建，多级委托路径直接完整显示，状态与记录保留。
336		reopened, err := Open(path)
337		if err != nil {
338			t.Fatalf("reopen: %v", err)
339		}
340		defer reopened.Close()
341		v, ok, err := reopened.VoteProposal("gip-reopen-chain")
342		if err != nil || !ok {
343			t.Fatalf("query after reopen: %v ok=%v", err, ok)
344		}
345		want := map[string]MemberView{
346			"a": {ID: "a", Weight: 1, Path: []string{"a", "b", "c"}, Delegate: "c", Direct: "b"},
347			"b": {ID: "b", Weight: 2, Path: []string{"b", "c"}, Delegate: "c", Direct: "c"},
348			"c": {ID: "c", Weight: 4, Path: []string{"c"}, Delegate: "c", Direct: ""},
349			"d": {ID: "d", Weight: 8, Path: []string{"d", "b", "c"}, Delegate: "c", Direct: "b"},
350		}
351		assertMemberViews(t, "reopen", memberPaths(v), want)
352		if v.State != "executed" || v.Tally == nil || !v.Tally.Passed {
353			t.Fatalf("state/tally after reopen: state=%s tally=%+v", v.State, v.Tally)
354		}
355		if len(v.Ballots) != 1 || v.Ballots[0].Representative != "c" || v.Ballots[0].Weight != 15 {
356			t.Fatalf("ballot after reopen: %+v", v.Ballots)
357		}
358		if r, ok, _ := reopened.Receipt("gip-reopen-chain"); !ok || r.ExecutedAt != 10 {
359			t.Fatalf("receipt after reopen: %+v ok=%v", r, ok)
360		}
361	}
