401	func TestDelegationChains(t *testing.T) {
402		store, _ := openTempStore(t, 1000)
403		defer store.Close()
404		in := &CreateVoteInput{
405			ID:      "gip-chain",
406			Members: []VoteMember{{ID: "a", Weight: 1}, {ID: "b", Weight: 2}, {ID: "c", Weight: 4}, {ID: "d", Weight: 8}, {ID: "e", Weight: 16}},
407			// a -> b -> c(停止)；d -> c；e 自代。
408			Delegations: []Delegation{{From: "a", To: "b"}, {From: "b", To: "c"}, {From: "d", To: "c"}},
409			Quorum:      15, StartAt: 0, Deadline: 10, TimelockEnd: 10,
410		}
411		view := mustCreateVote(t, store, in)
412		wantPath := map[string][]string{
413			"a": {"a", "b", "c"},
414			"b": {"b", "c"},
415			"c": {"c"},
416			"d": {"d", "c"},
417			"e": {"e"},
418		}
419		wantHead := map[string]string{"a": "c", "b": "c", "c": "c", "d": "c", "e": "e"}
420		for _, m := range view.Members {
421			if !equalStrings(m.Path, wantPath[m.ID]) {
422				t.Errorf("member %s path=%v want %v", m.ID, m.Path, wantPath[m.ID])
423			}
424			if m.Delegate != wantHead[m.ID] {
425				t.Errorf("member %s head=%s want %s", m.ID, m.Delegate, wantHead[m.ID])
426			}
427		}
428	
429		// 已委托出去的成员不能直接投票；最终代表 c 归集 1+2+4+8=15。
430		if _, err := store.CastVote("gip-chain", "a", true, 5); !errors.Is(err, ErrVoteRejected) {
431			t.Fatalf("delegated member voted: %v", err)
