662	func TestConcurrentVotingAndTally(t *testing.T) {
663		store, _ := openTempStore(t, 1000)
664		defer store.Close()
665		in := baseVoteInput("gip-conc")
666		mustCreateVote(t, store, in)
667	
668		// 两名代表在同一时刻反复投同一选择；只能各成功一次且票据不重复。
669		var wg sync.WaitGroup
670		errs := make(chan error, 64)
671		start := make(chan struct{})
672		vote := func(voter string, support bool, now int64) {
673			defer wg.Done()
674			<-start
675			if _, err := store.CastVote("gip-conc", voter, support, int64(now)); err != nil {
676				errs <- err
677			}
678		}
679		for i := 0; i < 16; i++ {
680			wg.Add(2)
681			go vote("alice", true, 150)
682			go vote("dave", false, 150)
683		}
684		close(start)
685		wg.Wait()
686		close(errs)
687		for err := range errs {
688			t.Errorf("concurrent identical vote: %v", err)
689		}
690		v, _, _ := store.VoteProposal("gip-conc")
691		if len(v.Ballots) != 2 {
692			t.Fatalf("ballot count=%d, want 2", len(v.Ballots))
693		}
694	
695		// 计票与投票并发：只有先于计票成功的票进入结论；二者由同一把锁串行。
696		in2 := baseVoteInput("gip-conc2")
697		in2.Quorum = 1000
698		mustCreateVote(t, store, in2)
699		var wg2 sync.WaitGroup
700		start2 := make(chan struct{})
701		wg2.Add(1)
702		go func() { // 迟到的票：可能在计票前或后
703			defer wg2.Done()
704			<-start2
705			_, _ = store.CastVote("gip-conc2", "dave", false, 150)
706		}()
707		wg2.Add(1)
708		go func() {
709			defer wg2.Done()
710			<-start2
711			_, _ = store.TallyVote("gip-conc2", 200)
712		}()
713		close(start2)
714		wg2.Wait()
715		v2, _, _ := store.VoteProposal("gip-conc2")
716		if v2.Tally == nil {
717			t.Fatal("proposal not tallied")
718		}
719		// 结论必须能由已保存票据重放（打开/提交时的严格校验兜底；这里再显式断言）。
720		var forW, againstW int64
721		for _, b := range v2.Ballots {
722			if b.Support {
723				forW += b.Weight
724			} else {
725				againstW += b.Weight
726			}
727		}
728		if forW != v2.Tally.ForWeight || againstW != v2.Tally.AgainstWeight {
729			t.Fatalf("tally %+v inconsistent with ballots for=%d against=%d", v2.Tally, forW, againstW)
730		}
731	}
