1587	  "balances": {},
1588	  "proposals": {},
1589	  "receipts": [],
1590	  "vote_proposals": {
1591	    "gip-fz": {
1592	      "id": "gip-fz",
1593	      "state": "voting",
1594	      "members": [{"id": "a", "weight": 5}, {"id": "b", "weight": 5}],
1595	      "delegations": [],
1596	      "quorum": 1,
1597	      "start_at": 0,
1598	      "deadline": 10,
1599	      "timelock_end": 10,
1600	      "actions": [],
1601	      "ballots": [{"representative": "b", "weight": 5, "support": false, "voted_at": 0}]
1602	    }
1603	  }
1604	}
1605	`
1606		if err := os.WriteFile(handwritten, []byte(raw), 0o600); err != nil {
