1695		// gip-passed：alice 600 赞成、反对 0，恰好达到法定人数而通过；
1696		// gip-rejected：dave 400 反对、赞成 0，参与不足而拒绝；
1697		// gip-executed：与 gip-passed 相同并已在时间锁后执行。
1698		passed := baseVoteInput("gip-passed")
