1804				msg := err.Error()
1805				for _, want := range []string{`"` + tc.id + `"`, "tally", `"` + tc.field + `"`, tc.causeWord} {
1806					if !strings.Contains(msg, want) {
1807						t.Fatalf("error %q missing %q", msg, want)
1808					}
1809				}
1810	
1811				// 原文件内容必须原样保留（失败不回写、不把缺失权重补成 0）。
1812				if got, rerr := os.ReadFile(bad); rerr != nil || string(got) != string(tc.raw) {
1813					t.Fatalf("corrupt file was modified on rejected Open")
1814				}
1815	
1816				// 重复打开仍以同一损坏分类拒绝，绝不返回可用句柄给出部分结果。
1817				s2, e := Open(bad)
1818				if !errors.Is(e, ErrStateCorrupt) {
1819					if s2 != nil {
1820						s2.Close()
1821					}
1822					t.Fatalf("reopen err=%v, want ErrStateCorrupt", e)
1823				}
1824			})
1825		}
1826	}
1827	
1828	// TestIncompleteTallyOpsRejectAndKeepFile：计票结果缺损的文件上，查询与
1829	// 计票/投票操作一律返回 ErrStateCorrupt，不给出部分结果、不因请求同库内另一项
1830	// 正常提案而忽略损坏、不改写文件，写入操作也不能借机把缺失权重补成零后保存。
1831	func TestIncompleteTallyOpsRejectAndKeepFile(t *testing.T) {
1832		dir := t.TempDir()
1833		path := filepath.Join(dir, "treasury.json")
1834		store, err := InitTreasury(path, 1000)
1835		if err != nil {
1836			t.Fatal(err)
1837		}
1838		// gip-tally-ops：已计票通过（for=600/against=0）；gip-still-voting：仍在投票。
1839		mustCreateVote(t, store, baseVoteInput("gip-tally-ops"))
1840		if _, err := store.CastVote("gip-tally-ops", "alice", true, 150); err != nil {
1841			t.Fatal(err)
1842		}
1843		if _, err := store.TallyVote("gip-tally-ops", 200); err != nil {
1844			t.Fatal(err)
1845		}
1846		mustCreateVote(t, store, baseVoteInput("gip-still-voting"))
1847		mustRegister(t, store, "gip-spent", 0, "transfer:audits:100")
1848		if _, err := store.Execute("gip-spent", 0); err != nil {
1849			t.Fatal(err)
1850		}
1851		store.Close()
1852	
1853		good, err := os.ReadFile(path)
1854		if err != nil {
1855			t.Fatal(err)
1856		}
1857		var clone map[string]any
1858		if err := json.Unmarshal(good, &clone); err != nil {
1859			t.Fatal(err)
1860		}
1861		// 删除已计票结果的 against_weight：真实反对票重恰好为 0，
1862		// 若被默认补零，这份缺损记录会被误当成有效的首次计票结果。
1863		delete(clone["vote_proposals"].(map[string]any)["gip-tally-ops"].(map[string]any)["tally"].(map[string]any), "against_weight")
1864		bad, err := json.MarshalIndent(clone, "", "  ")
1865		if err != nil {
1866			t.Fatal(err)
1867		}
1868		bad = append(bad, '\n')
1869		if err := os.WriteFile(path, bad, 0o600); err != nil {
1870			t.Fatal(err)
1871		}
1872	
1873		// 打开即拒绝，不返回可用句柄。
1874		s, err := Open(path)
1875		if !errors.Is(err, ErrStateCorrupt) {
1876			t.Fatalf("Open err=%v, want ErrStateCorrupt", err)
1877		}
1878		if s != nil {
1879			t.Fatal("corrupt open must not return a usable store")
1880		}
1881		if got, rerr := os.ReadFile(path); rerr != nil || string(got) != string(bad) {
1882			t.Fatalf("corrupt file was normalized or rewritten")
1883		}
1884	
1885		// 用一个真实打开的句柄，随后在句柄之外把文件改坏，下一次读取/操作必须拒绝。
1886		recoverPath := filepath.Join(dir, "recover.json")
1887		if err := os.WriteFile(recoverPath, good, 0o600); err != nil {
1888			t.Fatal(err)
1889		}
1890		live, err := Open(recoverPath)
1891		if err != nil {
1892			t.Fatal(err)
1893		}
1894		defer live.Close()
1895		if bal, err := live.TreasuryBalance(); err != nil || bal != 900 {
1896			t.Fatalf("balance before corruption=%d err=%v", bal, err)
1897		}
1898		if err := os.WriteFile(recoverPath, bad, 0o600); err != nil {
1899			t.Fatal(err)
1900		}
1901		if _, err := live.TreasuryBalance(); !errors.Is(err, ErrStateCorrupt) {
1902			t.Fatalf("TreasuryBalance after corruption err=%v, want ErrStateCorrupt", err)
1903		}
1904		if _, _, err := live.VoteProposal("gip-tally-ops"); !errors.Is(err, ErrStateCorrupt) {
1905			t.Fatalf("VoteProposal(corrupt) after corruption err=%v", err)
1906		}
1907		// 请求同库内另一项正常提案同样必须拒绝，不得忽略损坏。
1908		if _, _, err := live.VoteProposal("gip-still-voting"); !errors.Is(err, ErrStateCorrupt) {
1909			t.Fatalf("VoteProposal(healthy) after corruption err=%v", err)
1910		}
1911		if _, err := live.VoteProposals(); !errors.Is(err, ErrStateCorrupt) {
1912			t.Fatalf("VoteProposals after corruption err=%v", err)
1913		}
1914		if _, err := live.ProposalsSnapshot(); !errors.Is(err, ErrStateCorrupt) {
1915			t.Fatalf("ProposalsSnapshot after corruption err=%v", err)
1916		}
1917		// 再次计票不得返回由其余字段组成的部分结果。
1918		if _, err := live.TallyVote("gip-tally-ops", 200); !errors.Is(err, ErrStateCorrupt) {
1919			t.Fatalf("TallyVote(corrupt) after corruption err=%v", err)
1920		}
1921		// 对另一项正常提案首次计票同样拒绝，且不得借机改写状态文件。
1922		if _, err := live.TallyVote("gip-still-voting", 200); !errors.Is(err, ErrStateCorrupt) {
1923			t.Fatalf("TallyVote(healthy) after corruption err=%v", err)
1924		}
1925		if _, err := live.CastVote("gip-still-voting", "dave", false, 150); !errors.Is(err, ErrStateCorrupt) {
1926			t.Fatalf("CastVote after corruption err=%v", err)
1927		}
1928		if _, err := live.BalanceSnapshot(); !errors.Is(err, ErrStateCorrupt) {
1929			t.Fatalf("BalanceSnapshot after corruption err=%v", err)
1930		}
1931		// 失败后文件字节保持损坏被发现时的原样（未回写、未把缺失权重补成 0）。
1932		if got, rerr := os.ReadFile(recoverPath); rerr != nil || string(got) != string(bad) {
1933			t.Fatalf("failed ops rewrote or normalized the state file")
1934		}
1935	}
1936	
1937	// TestExplicitZeroTallyWeightsLegal：计票结果中明确写出的整数 0 是合法权重
1938	// （该侧或两侧都没有票），不得当成缺失；保存的结论仍按逐票明细重放核对，
1939	// 再次计票返回首次结论。
1940	func TestExplicitZeroTallyWeightsLegal(t *testing.T) {
1941		dir := t.TempDir()
1942		handwritten := filepath.Join(dir, "handwritten.json")
1943		raw := `{
1944	  "magic": "govflow-treasury-state",
1945	  "version": 1,
1946	  "initial_treasury": 1000,
1947	  "treasury": 1000,
1948	  "balances": {},
1949	  "proposals": {},
1950	  "receipts": [],
1951	  "vote_proposals": {
1952	    "gip-zero": {
1953	      "id": "gip-zero",
1954	      "state": "rejected",
1955	      "members": [{"id": "a", "weight": 5}],
1956	      "delegations": [],
1957	      "quorum": 1,
1958	      "start_at": 0,
1959	      "deadline": 10,
1960	      "timelock_end": 10,
1961	      "actions": [],
1962	      "ballots": [],
1963	      "tally": {"for_weight": 0, "against_weight": 0, "tallied_at": 10}
1964	    },
1965	    "gip-zerowin": {
1966	      "id": "gip-zerowin",
1967	      "state": "passed",
1968	      "members": [{"id": "a", "weight": 5}],
1969	      "delegations": [],
1970	      "quorum": 1,
1971	      "start_at": 0,
1972	      "deadline": 10,
1973	      "timelock_end": 10,
1974	      "actions": [],
1975	      "ballots": [{"representative": "a", "weight": 5, "support": true, "voted_at": 3}],
1976	      "tally": {"for_weight": 5, "against_weight": 0, "tallied_at": 10}
1977	    }
1978	  }
1979	}
1980	`
1981		if err := os.WriteFile(handwritten, []byte(raw), 0o600); err != nil {
1982			t.Fatal(err)
1983		}
1984		s, err := Open(handwritten)
1985		if err != nil {
1986			t.Fatalf("explicit zero tally weights rejected: %v", err)
1987		}
1988		defer s.Close()
1989	
1990		// 双方都明确写出 0：无票提案的合法拒绝结论。
1991		v, ok, err := s.VoteProposal("gip-zero")
1992		if err != nil || !ok {
1993			t.Fatalf("query gip-zero: %v ok=%v", err, ok)
1994		}
1995		if v.Tally == nil || v.Tally.ForWeight != 0 || v.Tally.AgainstWeight != 0 ||
1996			v.Tally.Turnout != 0 || v.Tally.Passed || v.Tally.TalliedAt != 10 {
1997			t.Fatalf("zero tally misread: %+v", v.Tally)
1998		}
1999		// 再次计票返回首次结论（tallied_at 保持 10），不重新计票。
2000		res, err := s.TallyVote("gip-zero", 20)
2001		if err != nil {
2002			t.Fatalf("re-tally gip-zero: %v", err)
2003		}
2004		if res.Passed || res.TalliedAt != 10 || res.ForWeight != 0 || res.AgainstWeight != 0 {
2005			t.Fatalf("re-tally must return first result: %+v", res)
2006		}
2007	
2008		// 反对侧明确写出 0：合法通过结论，重放核对一致。
2009		v2, ok, err := s.VoteProposal("gip-zerowin")
2010		if err != nil || !ok {
2011			t.Fatalf("query gip-zerowin: %v ok=%v", err, ok)
2012		}
2013		if v2.Tally == nil || v2.Tally.ForWeight != 5 || v2.Tally.AgainstWeight != 0 || !v2.Tally.Passed {
2014			t.Fatalf("zero against weight misread: %+v", v2.Tally)
2015		}
2016	}
2017	
2018	// TestCreateVoteRejectsInvalidUTF8：提案编号、成员编号或动作原文含有非法
2019	// UTF-8 字节（非法首字节、残缺多字节序列、UTF-8 形式直接编码的代理码位）
2020	// 时整项创建失败，错误分类为 ErrInvalidProposal，且说明是哪类文本、
2021	// 成员/动作在提交列表中的位置；状态文件逐字节保持原样。
2022	func TestCreateVoteRejectsInvalidUTF8(t *testing.T) {
2023		store, path := openTempStore(t, 1000)
2024		defer store.Close()
2025	
2026		// 状态中先存在一项编号含真实 U+FFFD 的合法提案与一笔登记提案，
2027		// 验证失败不重试/覆盖已有内容，已有提案、票据与余额不受影响。
2028		fffdIn := baseVoteInput("gip-�")
2029		mustCreateVote(t, store, fffdIn)
2030		mustRegister(t, store, "gip-reg", 300, "transfer:a:1")
2031		before, err := os.ReadFile(path)
2032		if err != nil {
2033			t.Fatalf("read state: %v", err)
2034		}
2035	
2036		cases := []struct {
2037			name      string
2038			mutate    func(in *CreateVoteInput)
2039			wantInErr []string
2040		}{
2041			{"proposal id illegal byte", func(in *CreateVoteInput) {
2042				in.ID = "gip-\xff"
2043			}, []string{"proposal id", "UTF-8"}},
2044			{"proposal id truncated rune", func(in *CreateVoteInput) {
2045				in.ID = "gip-\xe4\xb8" // “中”缺少最后一个字节
2046			}, []string{"proposal id", "UTF-8"}},
2047			{"proposal id encoded surrogate", func(in *CreateVoteInput) {
2048				in.ID = "gip-\xed\xa0\x80" // UTF-8 形式直接编码的 U+D800
2049			}, []string{"proposal id", "UTF-8"}},
2050			{"member id illegal byte", func(in *CreateVoteInput) {
2051				in.Members[1].ID = "bo\xffb"
2052			}, []string{"member 1", "UTF-8"}},
2053			{"member id truncated rune", func(in *CreateVoteInput) {
2054				in.Members[3].ID = "\xe4\xb8"
2055			}, []string{"member 3", "UTF-8"}},
2056			{"member id encoded surrogate", func(in *CreateVoteInput) {
2057				in.Members[0].ID = "\xed\xb0\x80" // UTF-8 形式直接编码的 U+DC00
2058			}, []string{"member 0", "UTF-8"}},
2059			{"action text illegal byte", func(in *CreateVoteInput) {
2060				in.Actions[0] = "transfer:audits:\xff"
2061			}, []string{"action 0", "UTF-8"}},
2062			{"action text truncated rune", func(in *CreateVoteInput) {
2063				in.Actions = append(in.Actions, "\xf0\x9f\x98") // 表情缺少最后一个字节
2064			}, []string{"action 1", "UTF-8"}},
2065		}
2066		for _, tc := range cases {
2067			t.Run(tc.name, func(t *testing.T) {
2068				in := baseVoteInput("bad-" + strings.ReplaceAll(tc.name, " ", "-"))
2069				tc.mutate(in)
2070				_, existed, err := store.CreateVoteProposal(in)
2071				if err == nil || existed {
2072					t.Fatalf("expected rejection, existed=%v err=%v", existed, err)
2073				}
2074				if !errors.Is(err, ErrInvalidProposal) {
2075					t.Fatalf("err=%v, want ErrInvalidProposal", err)
2076				}
2077				for _, want := range tc.wantInErr {
2078					if !strings.Contains(err.Error(), want) {
2079						t.Fatalf("err=%q, want substring %q", err.Error(), want)
2080					}
2081				}
2082			})
2083		}
2084	
2085		// 非法字节输入落盘时会被改写成真实 U+FFFD，恰好等于已存在的合法编号：
2086		// 仍必须整项失败（ErrInvalidProposal），不得当作该编号的相同内容重试，
2087		// 更不得覆盖它。
2088		retry := baseVoteInput("gip-\xef\xbf") // “�”缺少最后一个字节
2089		if _, existed, err := store.CreateVoteProposal(retry); err == nil || existed ||
2090			!errors.Is(err, ErrInvalidProposal) {
2091			t.Fatalf("invalid-UTF-8 collision with real U+FFFD id: existed=%v err=%v", existed, err)
2092		}
2093	
2094		// 状态文件逐字节保持原样；已有合法提案仍可按原编号查询。
2095		after, err := os.ReadFile(path)
2096		if err != nil {
2097			t.Fatalf("read state: %v", err)
2098		}
2099		if string(after) != string(before) {
2100			t.Fatalf("state file changed after rejected creates")
2101		}
2102		v, ok, err := store.VoteProposal("gip-�")
2103		if err != nil || !ok || v.ID != "gip-�" {
2104			t.Fatalf("existing U+FFFD proposal: ok=%v err=%v view=%+v", ok, err, v)
2105		}
2106		if bal, err := store.TreasuryBalance(); err != nil || bal != 1000 {
2107			t.Fatalf("treasury changed: bal=%d err=%v", bal, err)
2108		}
2109	}
2110	
2111	// TestCreateVotePreservesValidText：中文、表情、用户明确写出的 U+FFFD 以及
2112	// 由反斜杠与普通字母组成的字面文本（如 "\uD800"：创建参数不是 JSON 字符串，
2113	// 不得把其中看似 Unicode 转义的文字重解释成字符）都按原文保存与展示。
2114	// 编码合法但动作格式错误的文本照常创建，由执行操作按现有规则拒绝。
2115	func TestCreateVotePreservesValidText(t *testing.T) {
2116		store, path := openTempStore(t, 1000)
2117		in := &CreateVoteInput{
2118			ID: "提案-�-😀",
2119			Members: []VoteMember{
2120				{ID: "成员甲", Weight: 100},
2121				{ID: "smi�le-😀", Weight: 200},
2122				{ID: `back\uD800slash`, Weight: 300}, // 反斜杠 + 普通字母的字面文本
2123			},
2124			Quorum:      400,
2125			StartAt:     10,
2126			Deadline:    20,
2127			TimelockEnd: 30,
2128			Actions: []string{
2129				"transfer:账户:100",
2130				`literal FFFD stays text`,
2131				"not-a-transfer-action", // 编码合法但格式错误：创建仍允许
2132			},
2133		}
2134		view := mustCreateVote(t, store, in)
2135		if view.ID != in.ID {
2136			t.Fatalf("view id = %q, want %q", view.ID, in.ID)
2137		}
2138		for i, m := range view.Members {
2139			if m.ID != in.Members[i].ID {
2140				t.Fatalf("member %d id = %q, want %q", i, m.ID, in.Members[i].ID)
2141			}
2142		}
2143		if !sameActions(view.Actions, in.Actions) {
2144			t.Fatalf("view actions = %q, want %q", view.Actions, in.Actions)
2145		}
2146		if err := store.Close(); err != nil {
2147			t.Fatalf("close: %v", err)
2148		}
2149	
2150		// 重新打开后查询仍逐字展示原文。
2151		reopened, err := Open(path)
2152		if err != nil {
2153			t.Fatalf("reopen: %v", err)
2154		}
2155		defer reopened.Close()
2156		got, ok, err := reopened.VoteProposal(in.ID)
2157		if err != nil || !ok {
2158			t.Fatalf("query after reopen: ok=%v err=%v", ok, err)
2159		}
2160		if got.ID != in.ID {
2161			t.Fatalf("reopened id = %q, want %q", got.ID, in.ID)
2162		}
2163		for i, m := range got.Members {
2164			if m.ID != in.Members[i].ID {
2165				t.Fatalf("reopened member %d id = %q, want %q", i, m.ID, in.Members[i].ID)
2166			}
2167		}
2168		if !sameActions(got.Actions, in.Actions) {
2169			t.Fatalf("reopened actions = %q, want %q", got.Actions, in.Actions)
2170		}
2171	
2172		// 格式错误的动作在执行时才被拒绝，创建入口不提前改变动作资格。
2173		if _, err := reopened.Execute(in.ID, 30); err == nil {
2174			t.Fatalf("execute with malformed action must fail")
2175		}
2176	}
