474	// sameActions 将 nil 与空切片视为等价，其余按顺序逐字比较。
475	func sameActions(a, b []string) bool {
476		if len(a) != len(b) {
477			return false
478		}
479		for i := range a {
480			if a[i] != b[i] {
481				return false
482			}
483		}
484		return true
485	}
