518	// proposalOwners 将两个来源的提案编号映射到状态、时间锁与动作，供凭据重放交叉校验。
519	func proposalOwnerState(state *storedState, id string) (string, int64, []string, bool) {
520		if p, ok := state.Proposals[id]; ok {
521			return p.State, p.TimelockEnd, p.Actions, true
522		}
523		if vp, ok := state.VoteProposals[id]; ok {
524			return vp.State, vp.TimelockEnd, vp.Actions, true
525		}
526		return "", 0, nil, false
527	}
