529	// Execute 按编号执行一项提案。调用方通过 now 提供当前时间。
530	// 只有 passed 状态、now 已达到时间锁且动作非空的提案可以首次执行；
531	// 成功后状态变为 executed 并返回凭据。资格不符、动作格式错误、余额不足、
532	// 金额计算溢出都返回明确原因，整项提案不产生部分转账，也不消耗执行机会。
533	// 已完成提案再次执行（即使 now 不同）直接返回首次成功凭据。
534	func (s *Store) Execute(id string, now int64) (*Receipt, error) {
535		commit, err := s.begin()
536		if err != nil {
537			return nil, err
538		}
539		defer commit()
540	
541		state, err := s.loadLocked()
542		if err != nil {
543			return nil, err
544		}
545		target := resolveExecutable(state, id)
546		if target == nil {
547			return nil, fmt.Errorf("%w: %s", ErrProposalNotFound, id)
548		}
549		if target.state == "executed" {
550			if rcpt := findReceipt(state.Receipts, id); rcpt != nil {
551				return cloneReceipt(rcpt), nil
552			}
553			return nil, fmt.Errorf("%w: executed proposal %s has no receipt", ErrStateCorrupt, id)
554		}
555		if target.state != "passed" {
556			return nil, execReject(fmt.Sprintf("proposal %s is not passed (state=%s)", id, target.state))
557		}
558		if now < target.timelockEnd {
559			return nil, execReject(fmt.Sprintf("timelock not reached for %s: now=%d timelock_end=%d", id, now, target.timelockEnd))
560		}
561		if len(target.actions) == 0 {
562			return nil, execReject(fmt.Sprintf("proposal %s has no actions", id))
563		}
564	
565		// 第一阶段：在副本上按统一转账规则（planTransfers）校验并预演全部
566		// 动作。任何一步失败都直接返回，副本之外的状态不落盘。
567		steps, simTreasury, simBalances, perr := planTransfers(target.actions, state.Treasury, state.Balances)
568		if perr != nil {
569			return nil, perr
570		}
571	
572		// 第二阶段：全部预演成功后构造凭据并一次性原子提交。
573		receipt := &Receipt{
574			ProposalID: id,
575			ExecutedAt: now,
576			Order:      int64(len(state.Receipts)),
577			Actions:    make([]ActionReceipt, 0, len(steps)),
578		}
579		// 同步填上字段原始片段，使“提交前校验”与“打开重放校验”走同一份
580		// executed_at/order 判定时不会把本进程新建的凭据误判为字段缺失。
581		receipt.executedAtRaw, _ = json.Marshal(now)
582		receipt.orderRaw, _ = json.Marshal(receipt.Order)
583		for i, st := range steps {
584			receipt.Actions = append(receipt.Actions, st.actionReceipt(i, target.actions[i]))
585		}
586		state.Treasury = simTreasury
587		state.Balances = simBalances
588		target.markExecuted()
589		state.Receipts = append(state.Receipts, receipt)
590	
591		if err := s.commitLocked(state); err != nil {
592			return nil, err
593		}
594		return cloneReceipt(receipt), nil
595	}
596	
597	func findReceipt(receipts []*Receipt, id string) *Receipt {
598		for _, r := range receipts {
599			if r.ProposalID == id {
600				return r
601			}
602		}
603		return nil
604	}
605	
606	func cloneReceipt(r *Receipt) *Receipt {
607		if r == nil {
608			return nil
609		}
610		copied := *r
611		if r.Actions != nil {
612			copied.Actions = make([]ActionReceipt, len(r.Actions))
613			copy(copied.Actions, r.Actions)
614		}
615		return &copied
616	}
