774	// ---- 持久化 ----
775	
776	// loadLocked 读取、严格解析并重放校验状态文件。调用方必须持锁。
777	func (s *Store) loadLocked() (*storedState, error) {
778		raw, err := os.ReadFile(s.path)
779		if err != nil {
780			return nil, err
781		}
782		if len(bytes.TrimSpace(raw)) == 0 {
783			return nil, fmt.Errorf("%w: %s: file is empty", ErrStateCorrupt, s.path)
784		}
785		// 先于结构扫描与解码逐字节校验字符串：非法 UTF-8 与未配对代理项转义
786		// 会被 encoding/json 悄悄改写成 U+FFFD 且不报错，必须在此明确拒绝，
787		// 使被改写的编号/账户名/动作原文不可能参与后续任何匹配与重放。
788		if err := checkStrictStrings(raw); err != nil {
789			return nil, fmt.Errorf("%w: %s: %v", ErrStateCorrupt, s.path, err)
790		}
791		if err := checkStateStructure(raw); err != nil {
792			return nil, fmt.Errorf("%w: %s: %v", ErrStateCorrupt, s.path, err)
793		}
794		var state storedState
795		dec := json.NewDecoder(bytes.NewReader(raw))
796		dec.DisallowUnknownFields()
797		if err := dec.Decode(&state); err != nil {
798			return nil, fmt.Errorf("%w: %s: %v", ErrStateCorrupt, s.path, err)
799		}
800		// 拒绝单个合法 JSON 之后再拼接的额外内容（如 "{} {}"）。
801		var extra json.RawMessage
802		if err := dec.Decode(&extra); err != io.EOF {
803			if err == nil {
804				err = fmt.Errorf("unexpected trailing content after state document: %s", strings.TrimSpace(string(extra)))
805			}
806			return nil, fmt.Errorf("%w: %s: %v", ErrStateCorrupt, s.path, err)
807		}
808		if err := validateState(&state); err != nil {
809			return nil, fmt.Errorf("%w: %s: %v", ErrStateCorrupt, s.path, err)
810		}
811		return &state, nil
812	}
813	
814	// commitLocked 序列化状态并以“临时文件 + fsync + 原子改名 + 目录 fsync”提交。
815	// 任一步失败都保留上次完整状态。调用方必须持锁。
816	func (s *Store) commitLocked(state *storedState) error {
817		if err := validateState(state); err != nil {
818			return fmt.Errorf("refusing to persist invalid state: %w", err)
819		}
820		payload, err := json.MarshalIndent(state, "", "  ")
821		if err != nil {
822			return err
823		}
824		payload = append(payload, '\n')
825	
826		dir := filepath.Dir(s.path)
827		tmp, err := os.CreateTemp(dir, ".govflow-state-*")
828		if err != nil {
829			return err
830		}
831		tmpName := tmp.Name()
832		cleanup := func() { _ = os.Remove(tmpName) }
833		if _, err := tmp.Write(payload); err != nil {
834			_ = tmp.Close()
835			cleanup()
836			return err
837		}
838		if err := tmp.Sync(); err != nil {
839			_ = tmp.Close()
840			cleanup()
841			return err
842		}
843		if err := tmp.Close(); err != nil {
844			cleanup()
845			return err
846		}
847		if err := os.Chmod(tmpName, 0o600); err != nil {
848			cleanup()
849			return err
850		}
851		if err := os.Rename(tmpName, s.path); err != nil {
852			cleanup()
853			return err
854		}
855		if err := syncDir(dir); err != nil {
856			return err
857		}
858		return nil
859	}
860	
861	func syncDir(dir string) error {
862		d, err := os.Open(dir)
863		if err != nil {
864			return err
865		}
866		defer d.Close()
867		return d.Sync()
868	}
869	
870	// validateState 做结构校验并重放全部凭据，确认余额与凭据完全一致。
871	func validateState(state *storedState) error {
872		if state.Magic != stateMagic {
873			return fmt.Errorf("bad magic %q", state.Magic)
874		}
875		if state.Version != stateVersion {
876			return fmt.Errorf("unsupported state version %d", state.Version)
877		}
878		if state.InitialTreasury < 0 {
879			return errors.New("initial treasury balance is negative")
880		}
881		if state.Treasury < 0 {
882			return errors.New("treasury balance is negative")
883		}
884		if state.Balances == nil {
885			return errors.New("balances table is missing")
886		}
887		if state.Proposals == nil {
888			return errors.New("proposals table is missing")
889		}
890		if state.Receipts == nil {
891			return errors.New("receipts table is missing")
892		}
893		// VoteProposals 缺省视为空表：旧版本写出的状态文件不含投票提案，继续可读。
894		if state.VoteProposals == nil {
895			state.VoteProposals = map[string]*storedVoteProposal{}
896		}
897		for account, balance := range state.Balances {
898			if account == "" {
899				return errors.New("balance entry with empty account")
900			}
901			if balance < 0 {
902				return fmt.Errorf("balance of %q is negative", account)
903			}
904		}
905		for key, p := range state.Proposals {
906			if p == nil {
907				return fmt.Errorf("proposal %q is empty", key)
908			}
909			if p.ID != key || p.ID == "" {
910				return fmt.Errorf("proposal key %q does not match id %q", key, p.ID)
911			}
912			if p.State != "passed" && p.State != "executed" {
913				return fmt.Errorf("proposal %q has unknown state %q", p.ID, p.State)
914			}
915			// 动作原文登记时原样保存；空串或非法原文留待执行时拒绝。
916		}
917		if err := validateVoteProposals(state); err != nil {
918			return err
919		}
920	
921		// 重放凭据：从初始资金库余额出发，按成功顺序重放每笔转账，
922		// 校验凭据内的前后余额、最终资金库与各账户余额，并检查状态一致性。
923		simTreasury := state.InitialTreasury
924		simBalances := map[string]int64{}
925		seenReceipts := map[string]int{}
926		for order, rcpt := range state.Receipts {
927			if rcpt == nil {
928				return fmt.Errorf("receipt %d is empty", order)
929			}
930			// order 是执行留痕中明确保存的成功提交序号（0 起），必须显式写出、
931			// 为 int64 范围内的非负整数且恰好等于凭据在记录表中的位置：第一份
932			// 凭据缺 order 也不能补成 0。缺失/空值/类型不符/位置不符都带提案
933			// 编号与字段报损坏，不按数组位置重新编号。
934			if err := validateReceiptOrder(order, rcpt); err != nil {
935				return err
936			}
937			if prev, dup := seenReceipts[rcpt.ProposalID]; dup {
938				return fmt.Errorf("duplicate receipt for %q at positions %d and %d", rcpt.ProposalID, prev, order)
939			}
940			seenReceipts[rcpt.ProposalID] = order
941			ownerState, ownerTimelock, ownerActions, found := proposalOwnerState(state, rcpt.ProposalID)
942			if !found {
943				return fmt.Errorf("receipt %q references an unregistered proposal", rcpt.ProposalID)
944			}
945			if ownerState != "executed" {
946				return fmt.Errorf("proposal %q has receipt but state is %q", rcpt.ProposalID, ownerState)
947			}
948			// 保存的凭据与首次执行受同一条执行资格规则约束：executed_at 必须明确
949			// 写出且不得早于提案时间锁。登记提案与投票提案共用这一判断。
950			if err := validateReceiptExecutedAt(order, rcpt, ownerTimelock); err != nil {
951				return err
952			}
953			// 每项动作的 index 与四个余额字段（资金库/收款账户 × before/after）
954			// 都必须明确写出：任何一个缺失、为 null 或类型不符都判整份状态损坏，
955			// 不能按数组位置、转账金额、账户余额或其它凭据补出；明确写出的 0 是
956			// 合法记录（第一项动作的 index 0 必须显式保存）。
957			for i := range rcpt.Actions {
958				if err := validateReceiptActionIndex(rcpt.ProposalID, i, &rcpt.Actions[i]); err != nil {
959					return err
960				}
961				if err := validateReceiptActionBalances(rcpt.ProposalID, i, &rcpt.Actions[i]); err != nil {
962					return err
963				}
964			}
965			// 凭据声明的逐笔转账由统一转账规则（verifyReceiptTransfers）重放
966			// 核对：动作条数/编号/原文、资金库与收款账户前后余额任一不符都带
967			// 动作位置报损坏原因；本函数随即返回错误，整份状态被拒绝，重放结果
968			// 不会被查询或落盘采纳。
969			var verr error
970			simTreasury, verr = verifyReceiptTransfers(rcpt, ownerActions, simTreasury, simBalances)
971			if verr != nil {
972				return verr
973			}
974		}
975		if simTreasury != state.Treasury {
976			return fmt.Errorf("treasury balance %d does not match receipt replay %d", state.Treasury, simTreasury)
977		}
978		// 余额表的账户集合必须与成功凭据涉及的收款账户完全一致：缺少收款账户、
979		// 出现无凭据支持的账户（即使写成 0）或已记录余额不符都判整份状态损坏。
980		// 不能只按账户数量或仅遍历文件自身的键：把一个已收款账户换成数量相同、
981		// 余额写成 0 的陌生账户时，数量相等且缺失键在 map 中读到零值，会被误判
982		// 为合法。账户名排序后报告，使错误信息确定且可读；余额表的排列顺序本身
983		// 不影响判定。
984		savedAccounts := make([]string, 0, len(state.Balances))
985		for account := range state.Balances {
986			savedAccounts = append(savedAccounts, account)
987		}
988		replayAccounts := make([]string, 0, len(simBalances))
989		for account := range simBalances {
990			replayAccounts = append(replayAccounts, account)
991		}
992		sort.Strings(savedAccounts)
993		sort.Strings(replayAccounts)
994		var missing, unexpected []string
995		si, ri := 0, 0
996		for si < len(savedAccounts) || ri < len(replayAccounts) {
997			switch {
998			case ri == len(replayAccounts) || (si < len(savedAccounts) && savedAccounts[si] < replayAccounts[ri]):
999				unexpected = append(unexpected, savedAccounts[si])
1000				si++
1001			case si == len(savedAccounts) || savedAccounts[si] > replayAccounts[ri]:
1002				missing = append(missing, replayAccounts[ri])
1003				ri++
1004			default:
1005				si++
1006				ri++
1007			}
1008		}
1009		if len(missing) > 0 || len(unexpected) > 0 {
1010			problems := ""
1011			if len(missing) > 0 {
1012				problems = fmt.Sprintf("missing recipient account(s) %s with no balance record for funds actually received",
1013					strings.Join(quoteAccounts(missing), ", "))
1014			}
1015			if len(unexpected) > 0 {
1016				if problems != "" {
1017					problems += "; "
1018				}
1019				problems += fmt.Sprintf("account(s) %s have balance records but no successful receipt supports them (a zero balance does not make an unsupported account legal)",
1020					strings.Join(quoteAccounts(unexpected), ", "))
1021			}
1022			return fmt.Errorf("balance table is inconsistent with execution receipts: %s", problems)
1023		}
1024		for _, account := range replayAccounts {
1025			if balance := state.Balances[account]; balance != simBalances[account] {
1026				return fmt.Errorf("balance of %q is %d but receipt replay yields %d", account, balance, simBalances[account])
1027			}
1028		}
1029		// 已执行的提案必须有凭据；passed 提案不得有凭据（上面已部分保证）。
1030		for _, p := range state.Proposals {
1031			_, hasReceipt := seenReceipts[p.ID]
1032			if p.State == "executed" && !hasReceipt {
1033				return fmt.Errorf("proposal %q is executed without receipt", p.ID)
1034			}
1035		}
1036		for _, p := range state.VoteProposals {
1037			_, hasReceipt := seenReceipts[p.ID]
1038			if p.State == "executed" && !hasReceipt {
1039				return fmt.Errorf("voting proposal %q is executed without receipt", p.ID)
1040			}
1041		}
1042		return nil
1043	}
