1045	// quoteAccounts 给账户名列表逐个加上 Go 风格引号，便于在损坏原因中逐字定位。
1046	func quoteAccounts(accounts []string) []string {
1047		quoted := make([]string, len(accounts))
1048		for i, account := range accounts {
1049			quoted[i] = strconv.Quote(account)
1050		}
1051		return quoted
1052	}
