1097		if problem := requiredScalarProblem(ar.indexRaw, scalarInteger); problem != "" {
1098			return fmt.Errorf("receipt for proposal %q action %d field %q %s",
1099				id, position, "index", problem)
1100		}
1101		if ar.Index != int64(position) {
1102			return fmt.Errorf("receipt for proposal %q action %d field %q is %d, expected %d",
1103				id, position, "index", ar.Index, position)
1104		}
1105		return nil
1106	}
